// Webhook Signature Verification (DISABLED)
// NOTE: crypto module is disallowed in n8n 2.6+
// This workflow now performs basic payload validation only.
// Signature verification cannot be done in Code nodes.
// Rely on URL obscurity and payload structure validation.

const input = $input.first().json;
const service = input.service;
const payload = input.payload;

let isValid = true;
let error = null;

// Basic payload validation per service
switch (service) {
  case 'calcom':
    isValid = !!(payload?.triggerEvent && payload?.payload);
    if (!isValid) error = 'Invalid Cal.com payload structure';
    break;
  case 'calendly':
    isValid = !!(payload?.event && payload?.payload);
    if (!isValid) error = 'Invalid Calendly payload structure';
    break;
  case 'slack':
    isValid = !!(payload?.type || payload?.event || payload?.command);
    if (!isValid) error = 'Invalid Slack payload structure';
    break;
  case 'stripe':
    isValid = !!(payload?.type && payload?.data?.object);
    if (!isValid) error = 'Invalid Stripe payload structure';
    break;
  case 'resend':
    isValid = !!(payload?.type && payload?.data);
    if (!isValid) error = 'Invalid Resend payload structure';
    break;
  default:
    isValid = true; // Allow unknown services through with warning
    error = `Unknown service: ${service} - no validation applied`;
}

return {
  json: {
    isValid,
    service,
    error,
    note: 'Signature verification disabled (crypto not available in n8n 2.6+)',
    timestamp: new Date().toISOString()
  }
};
